CREATE TABLE app_users (id bigserial PRIMARY KEY, email varchar(255) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, role varchar(40) NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE', reset_token_hash varchar(64), reset_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_sessions (token_hash varchar(64) PRIMARY KEY, user_id bigint NOT NULL REFERENCES app_users(id), expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX app_sessions_user_idx ON app_sessions(user_id);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, actor_id bigint REFERENCES app_users(id), action varchar(100) NOT NULL, entity_type varchar(60) NOT NULL, entity_id bigint, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_time_idx ON audit_events(created_at DESC);
CREATE TABLE categories (id bigserial PRIMARY KEY, name varchar(120) NOT NULL UNIQUE);
CREATE TABLE products (id bigserial PRIMARY KEY, name varchar(255) NOT NULL, category_id bigint REFERENCES categories(id), unit varchar(30) NOT NULL DEFAULT 'EACH', active boolean NOT NULL DEFAULT true, reorder_threshold bigint NOT NULL DEFAULT 0 CHECK (reorder_threshold >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_name_idx ON products(lower(name));
CREATE TABLE product_variants (id bigserial PRIMARY KEY, product_id bigint NOT NULL REFERENCES products(id), sku varchar(80) NOT NULL UNIQUE, barcode varchar(120) UNIQUE, label varchar(120) NOT NULL DEFAULT 'Standard', selling_price numeric(14,2) NOT NULL CHECK (selling_price >= 0), purchase_cost numeric(14,2) NOT NULL CHECK (purchase_cost >= 0), active boolean NOT NULL DEFAULT true);
CREATE INDEX product_variants_product_idx ON product_variants(product_id);
CREATE TABLE warehouses (id bigserial PRIMARY KEY, name varchar(160) NOT NULL UNIQUE, code varchar(40) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE warehouse_locations (id bigserial PRIMARY KEY, warehouse_id bigint NOT NULL REFERENCES warehouses(id), code varchar(60) NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(warehouse_id,code), UNIQUE(id,warehouse_id));
CREATE TABLE stock_balances (variant_id bigint NOT NULL REFERENCES product_variants(id), location_id bigint NOT NULL REFERENCES warehouse_locations(id), on_hand bigint NOT NULL DEFAULT 0 CHECK (on_hand >= 0), reserved bigint NOT NULL DEFAULT 0 CHECK (reserved >= 0 AND reserved <= on_hand), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(variant_id,location_id));
CREATE INDEX stock_balances_location_idx ON stock_balances(location_id);
CREATE TABLE suppliers (id bigserial PRIMARY KEY, name varchar(255) NOT NULL, email varchar(255), phone varchar(80), status varchar(20) NOT NULL DEFAULT 'ACTIVE', lead_days integer NOT NULL DEFAULT 7 CHECK(lead_days >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_products (supplier_id bigint NOT NULL REFERENCES suppliers(id), variant_id bigint NOT NULL REFERENCES product_variants(id), PRIMARY KEY(supplier_id,variant_id));
CREATE TABLE customers (id bigserial PRIMARY KEY, name varchar(255) NOT NULL, email varchar(255), phone varchar(80), address text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_orders (id bigserial PRIMARY KEY, supplier_id bigint NOT NULL REFERENCES suppliers(id), status varchar(30) NOT NULL DEFAULT 'DRAFT', expected_at date, submitted_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_order_lines (id bigserial PRIMARY KEY, purchase_order_id bigint NOT NULL REFERENCES purchase_orders(id), variant_id bigint NOT NULL REFERENCES product_variants(id), quantity bigint NOT NULL CHECK(quantity > 0), received_quantity bigint NOT NULL DEFAULT 0 CHECK(received_quantity >= 0 AND received_quantity <= quantity), unit_cost numeric(14,2) NOT NULL CHECK(unit_cost >= 0));
CREATE INDEX purchase_lines_order_idx ON purchase_order_lines(purchase_order_id);
CREATE TABLE goods_receipts (id bigserial PRIMARY KEY, purchase_order_id bigint NOT NULL REFERENCES purchase_orders(id), external_ref varchar(120), received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(purchase_order_id,external_ref));
CREATE TABLE goods_receipt_lines (id bigserial PRIMARY KEY, receipt_id bigint NOT NULL REFERENCES goods_receipts(id), purchase_line_id bigint NOT NULL REFERENCES purchase_order_lines(id), location_id bigint NOT NULL REFERENCES warehouse_locations(id), quantity bigint NOT NULL CHECK(quantity > 0));
CREATE TABLE sales_orders (id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers(id), status varchar(30) NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, fulfilled_at timestamptz, cancelled_at timestamptz);
CREATE TABLE sales_lines (id bigserial PRIMARY KEY, sales_order_id bigint NOT NULL REFERENCES sales_orders(id), variant_id bigint NOT NULL REFERENCES product_variants(id), quantity bigint NOT NULL CHECK(quantity > 0), fulfilled_quantity bigint NOT NULL DEFAULT 0 CHECK(fulfilled_quantity >= 0 AND fulfilled_quantity <= quantity), unit_price numeric(14,2) NOT NULL CHECK(unit_price >= 0));
CREATE INDEX sales_lines_order_idx ON sales_lines(sales_order_id);
CREATE TABLE reservations (id bigserial PRIMARY KEY, sales_line_id bigint NOT NULL REFERENCES sales_lines(id), variant_id bigint NOT NULL REFERENCES product_variants(id), location_id bigint NOT NULL REFERENCES warehouse_locations(id), quantity bigint NOT NULL CHECK(quantity > 0), status varchar(20) NOT NULL DEFAULT 'ACTIVE', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reservations_expiry_idx ON reservations(expires_at) WHERE status='ACTIVE';
CREATE TABLE shipments (id bigserial PRIMARY KEY, sales_order_id bigint NOT NULL REFERENCES sales_orders(id), tracking_number varchar(120), status varchar(30) NOT NULL DEFAULT 'PACKED', created_at timestamptz NOT NULL DEFAULT now(), shipped_at timestamptz);
CREATE TABLE returns (id bigserial PRIMARY KEY, sales_line_id bigint NOT NULL REFERENCES sales_lines(id), location_id bigint NOT NULL REFERENCES warehouse_locations(id), quantity bigint NOT NULL CHECK(quantity > 0), reason text NOT NULL, idempotency_key varchar(180) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_commands (idempotency_key varchar(180) PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_movements (id bigserial PRIMARY KEY, variant_id bigint NOT NULL REFERENCES product_variants(id), location_id bigint NOT NULL REFERENCES warehouse_locations(id), delta bigint NOT NULL CHECK(delta <> 0), movement_type varchar(40) NOT NULL, reference_type varchar(40), reference_id bigint, idempotency_key varchar(180) NOT NULL UNIQUE, actor_id bigint REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX stock_movements_variant_time_idx ON stock_movements(variant_id,created_at DESC);
CREATE INDEX stock_movements_location_time_idx ON stock_movements(location_id,created_at DESC);
CREATE TABLE outbox_events (id bigserial PRIMARY KEY, event_type varchar(100) NOT NULL, aggregate_id bigint NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE INDEX outbox_pending_idx ON outbox_events(id) WHERE published_at IS NULL;
CREATE TABLE consumed_events (consumer_name varchar(100) NOT NULL, event_id bigint NOT NULL, consumed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_name,event_id));
